        if input_grid[r][c] != 0:
            positions.setdefault(input_grid[r][c], []).append((r, c))

for color, locs in sorted(positions.items()):
    locs.sort()
    print(f"Color {color}: {locs}")

# Check secondary diagonal symmetry
def check_secondary_diag_symmetry(grid):
    """Check if grid matches its secondary diagonal reflection"""
    h, w = grid.shape
    for r in range(h):
        for c in range(w):
            symmetric_r, symmetric_c = w - 1 - c, h - 1 - r
            if grid[r, c] != grid[symmetric_r, symmetric_c]:
                return False, (r, c, grid[r, c], symmetric_r, symmetric_c, grid[symmetric_r, symmetric_c])
    return True, None

print("\nSecondary diagonal symmetry check:")
symmetric, diffs = check_secondary_diag_symmetry(input_grid)
print(f"Symmetric: {symmetric}")
